  g_ui.wifi_keyboard = NULL;

  if (g_ui.center_panel != NULL)
    {
      lv_obj_clean(g_ui.center_panel);
      lv_obj_scroll_to_y(g_ui.center_panel, 0, LV_ANIM_OFF);
    }
