struct ui_demo_wifi_nsh_child_args
{
  const char *command;
  int write_fd;
};

static int ui_demo_wifi_nsh_child_entry(int argc, char *argv[])
{
  struct ui_demo_wifi_nsh_child_args *args;
  char *nsh_argv[] =
  {
    "nsh",
    NULL,
    NULL
  };
  uintptr_t args_ptr;
  int stdout_fd;
  int stderr_fd;
  int ret;

  if (argc < 2 || argv[1] == NULL)
    {
      return EXIT_FAILURE;
    }

  args_ptr = (uintptr_t)strtoul(argv[1], NULL, 16);
  args = (struct ui_demo_wifi_nsh_child_args *)args_ptr;
  if (args == NULL || args->command == NULL)
    {
      return EXIT_FAILURE;
    }

  stdout_fd = dup(1);
  stderr_fd = dup(2);
  if (stdout_fd < 0 || stderr_fd < 0)
    {
      if (stdout_fd >= 0)
        {
          close(stdout_fd);
        }

      if (stderr_fd >= 0)
        {
          close(stderr_fd);
        }

      close(args->write_fd);
      return EXIT_FAILURE;
    }

  fflush(stdout);
  fflush(stderr);
  if (dup2(args->write_fd, 1) < 0 || dup2(args->write_fd, 2) < 0)
    {
      (void)dup2(stdout_fd, 1);
      (void)dup2(stderr_fd, 2);
      close(stdout_fd);
      close(stderr_fd);
      close(args->write_fd);
      return EXIT_FAILURE;
    }

  close(args->write_fd);
  nsh_argv[1] = (char *)args->command;
  ret = nsh_system(2, nsh_argv);
  fflush(stdout);
  fflush(stderr);
  (void)dup2(stdout_fd, 1);
  (void)dup2(stderr_fd, 2);
  close(stdout_fd);
  close(stderr_fd);

  return ret == 0 ? EXIT_SUCCESS : EXIT_FAILURE;
}

static int ui_demo_wifi_run_command_with_nsh(const char *command,
                                             char *output,
                                             size_t output_len)
{
  struct ui_demo_wifi_nsh_child_args child_args;
  char args_arg[sizeof(uintptr_t) * 2 + 1];
  char *child_argv[] =
  {
    "ui_wifi_nsh",
    args_arg,
    NULL
  };
  int pipefd[2];
  int wait_status = 0;
  int pid;
  int ret;

  if (pipe(pipefd) < 0)
    {
      ret = errno == 0 ? -EIO : -errno;
      syslog(LOG_ERR, "%s: pipe failed command=%s ret=%d\n",
             UI_DEMO_WIFI_LOG_TAG, command, ret);
      return ret;
    }

  child_args.command = command;
  child_args.write_fd = pipefd[1];
  snprintf(args_arg, sizeof(args_arg), "%lx", (unsigned long)&child_args);
  pid = task_create("ui_wifi_nsh",
                    CONFIG_LVGL_APP_UI_DEMO_WIFI_TASK_PRIORITY,
                    CONFIG_LVGL_APP_UI_DEMO_WIFI_TASK_STACKSIZE,
                    ui_demo_wifi_nsh_child_entry,
                    child_argv);
  if (pid < 0)
    {
      ret = errno == 0 ? -EIO : -errno;
      close(pipefd[0]);
      close(pipefd[1]);
      return ret;
    }

  close(pipefd[1]);
  ui_demo_wifi_read_fd(pipefd[0], output, output_len);
  close(pipefd[0]);

  if (waitpid(pid, &wait_status, 0) < 0)
    {
      ret = errno == 0 ? -EIO : -errno;
      syslog(LOG_WARNING, "%s: waitpid failed ret=%d command=%s output=%s\n",
             UI_DEMO_WIFI_LOG_TAG, ret, command,
             output == NULL ? "" : output);
      return ret;
    }

  if (wait_status != 0)
    {
      syslog(LOG_WARNING,
             "%s: nsh command failed status=%d command=%s output=%s\n",
             UI_DEMO_WIFI_LOG_TAG, wait_status, command,
             output == NULL ? "" : output);
      return -EIO;
    }

  syslog(LOG_INFO, "%s: nsh command ok command=%s output=%s\n",
         UI_DEMO_WIFI_LOG_TAG, command, output == NULL ? "" : output);
  return 0;
}
