}

static int32_t ui_demo_wifi_signal_from_rssi(int32_t rssi)
{
  if (rssi == 0)
    {
      return 0;
    }

  if (rssi >= -35)
    {
      return 100;
    }

  if (rssi <= -95)
    {
      return 5;
    }

  return 5 + ((rssi + 95) * 95) / 60;
}

static bool ui_demo_wifi_parse_scan_line(const char *line,
                                         struct ui_demo_wifi_ap *ap)
{
  const char *ssid_start;
  const char *ssid_end;
  const char *channel_pos;
  const char *rssi_pos;
  unsigned long channel = 0;
  long rssi = 0;
  size_t ssid_len;

  if (line == NULL || ap == NULL)
    {
      return false;
    }

  ssid_start = strstr(line, "ssid=\"");
  if (ssid_start == NULL)
    {
      return false;
    }

  ssid_start += strlen("ssid=\"");
  ssid_end = strchr(ssid_start, '"');
  if (ssid_end == NULL || ssid_end == ssid_start)
    {
      return false;
    }

  memset(ap, 0, sizeof(*ap));
  ssid_len = (size_t)(ssid_end - ssid_start);
  if (ssid_len >= sizeof(ap->ssid))
    {
      ssid_len = sizeof(ap->ssid) - 1;
    }

  memcpy(ap->ssid, ssid_start, ssid_len);
  ap->ssid[ssid_len] = '\0';

  channel_pos = strstr(line, "ch=");
  if (channel_pos != NULL)
    {
      (void)sscanf(channel_pos, "ch=%lu", &channel);
    }

  rssi_pos = strstr(line, "rssi=");
  if (rssi_pos != NULL)
    {
      (void)sscanf(rssi_pos, "rssi=%ld", &rssi);
    }

  ap->channel = (uint32_t)channel;
  ap->rssi = (int32_t)rssi;
  ap->signal = ui_demo_wifi_signal_from_rssi(ap->rssi);
  snprintf(ap->status, sizeof(ap->status),
           "CH %lu  RSSI %ld dBm", channel, rssi);

  return true;
}

static void ui_demo_wifi_store_or_update_ap(struct ui_demo_wifi_ap *aps,
                                            size_t *count,
                                            const struct ui_demo_wifi_ap *ap)
{
  size_t i;

  for (i = 0; i < *count; i++)
    {
      if (strcmp(aps[i].ssid, ap->ssid) == 0)
        {
          if (ap->rssi > aps[i].rssi)
            {
              aps[i] = *ap;
            }

          return;
        }
    }

  if (*count < UI_DEMO_WIFI_MAX_APS)
    {
      aps[*count] = *ap;
      (*count)++;
    }
}

static size_t ui_demo_wifi_parse_scan_output(
  const char *output,
  struct ui_demo_wifi_ap *aps,
  size_t max_count)
{
  const char *cursor = output;
  size_t count = 0;

  while (cursor != NULL && *cursor != '\0' && count < max_count)
    {
      char line[256];
      struct ui_demo_wifi_ap ap;
      size_t len = 0;

      while (cursor[len] != '\0' && cursor[len] != '\n' &&
             len + 1 < sizeof(line))
        {
          line[len] = cursor[len];
          len++;
        }

      line[len] = '\0';

      while (cursor[len] != '\0' && cursor[len] != '\n')
        {
          len++;
        }

      cursor += len;
      if (*cursor == '\n')
        {
          cursor++;
        }

      if (ui_demo_wifi_parse_scan_line(line, &ap))
        {
          ui_demo_wifi_store_or_update_ap(aps, &count, &ap);
        }
    }

  return count;
}

static bool ui_demo_wifi_password_is_hex64(const char *password)
{
  size_t i;

  if (password == NULL || strlen(password) != 64)
    {
      return false;
    }

  for (i = 0; i < 64; i++)
    {
      char ch = password[i];

      if (!((ch >= '0' && ch <= '9') ||
            (ch >= 'a' && ch <= 'f') ||
            (ch >= 'A' && ch <= 'F')))
        {
          return false;
        }
    }

  return true;
}

static bool ui_demo_wifi_password_is_valid(const char *password)
{
  size_t len;

  if (password == NULL)
    {
      return false;
    }

  len = strlen(password);
  if (len == 0)
    {
      return true;
    }

  if (len >= 8 && len <= 63)
    {
      return true;
    }

  return ui_demo_wifi_password_is_hex64(password);
}

static bool ui_demo_wifi_quote_arg(const char *src, char *dst, size_t dst_len)
{
  size_t used = 0;

  if (src == NULL || dst == NULL || dst_len < 3)
    {
      return false;
    }

  dst[used++] = '"';
  while (*src != '\0')
    {
      char ch = *src++;

      if (ch == '\n' || ch == '\r')
        {
          return false;
        }

      if (ch == '"' || ch == '\\')
        {
          if (used + 2 >= dst_len)
            {
              return false;
            }

          dst[used++] = '\\';
          dst[used++] = ch;
        }
      else
        {
          if (used + 1 >= dst_len)
            {
              return false;
            }

          dst[used++] = ch;
        }
    }

  if (used + 1 >= dst_len)
    {
      return false;
    }

  dst[used++] = '"';
  dst[used] = '\0';
  return true;
}

static void ui_demo_wifi_describe_command_error(int ret,
                                                char *message,
                                                size_t message_len)
{
  if (ret == -ENOSYS)
    {
      snprintf(message, message_len,
               "系统未启用 WiFi shell 命令，请启用 NSH_LIBRARY 和 PIPES 后重试");
    }
  else if (ret == -ENOMEM)
    {
      snprintf(message, message_len,
               "系统内存不足，无法执行 WiFi 命令");
    }
  else
    {
      snprintf(message, message_len,
               "WiFi 命令执行失败，错误码 %d", ret);
    }
}

static bool ui_demo_wifi_parse_connect_result(const char *output,
                                              int *wlan_ret,
                                              int *connect_status,
                                              int *dhcp_ret,
                                              bool *has_dhcp)
{
  const char *wlan_pos;
  const char *dhcp_pos;

  *wlan_ret = 0;
  *connect_status = 0;
  *dhcp_ret = 0;
  *has_dhcp = false;

  wlan_pos = strstr(output, "wlan_start_sta ret=");
  if (wlan_pos == NULL)
    {
      return false;
    }

  if (sscanf(wlan_pos, "wlan_start_sta ret=%d status=%d",
             wlan_ret, connect_status) != 2)
    {
      return false;
    }

  dhcp_pos = strstr(output, "DHCP ret=");
  if (dhcp_pos != NULL &&
      sscanf(dhcp_pos, "DHCP ret=%d", dhcp_ret) == 1)
    {
      *has_dhcp = true;
    }

  return true;
}

static int ui_demo_wifi_scan_entry(int argc, char *argv[])
{
  struct ui_demo_wifi_ap aps[UI_DEMO_WIFI_MAX_APS];
  char command[32];
  char *output;
  bool need_start;
  uint32_t generation;
  size_t count = 0;
  int ret = 0;

  (void)argc;
  (void)argv;

  pthread_mutex_lock(&g_wifi_lock);
  need_start = g_wifi.scan_needs_start;
  g_wifi.scan_needs_start = false;
  generation = g_wifi.scan_generation;
  pthread_mutex_unlock(&g_wifi_lock);

  output = malloc(CONFIG_LVGL_APP_UI_DEMO_WIFI_CMD_OUTPUT_LEN);
  if (output == NULL)
    {
      pthread_mutex_lock(&g_wifi_lock);
      if (generation == g_wifi.generation)
        {
          g_wifi.scan_in_progress = false;
          g_wifi.enabled = false;
          g_wifi.status = UI_DEMO_WIFI_STATUS_ERROR;
          ui_demo_wifi_set_message_locked("内存不足，无法扫描 WiFi");
        }
      pthread_mutex_unlock(&g_wifi_lock);
      ui_demo_wifi_notify(UI_DEMO_WIFI_EVENT_SCAN_FINISHED);
      return -ENOMEM;
    }

  if (need_start)
    {
      ret = ui_demo_wifi_run_command("wifistart", output,
                                     CONFIG_LVGL_APP_UI_DEMO_WIFI_CMD_OUTPUT_LEN);
      if (ret < 0 || ui_demo_wifi_output_contains_failure(output))
        {
          char detail[UI_DEMO_WIFI_MESSAGE_LEN];

          ui_demo_wifi_describe_command_error(ret, detail, sizeof(detail));

          pthread_mutex_lock(&g_wifi_lock);
          if (generation == g_wifi.generation)
            {
              g_wifi.scan_in_progress = false;
              g_wifi.enabled = false;
              g_wifi.status = UI_DEMO_WIFI_STATUS_ERROR;
              ui_demo_wifi_set_message_locked("WiFi 启动失败：%s", detail);
            }
          pthread_mutex_unlock(&g_wifi_lock);
          free(output);
          ui_demo_wifi_notify(UI_DEMO_WIFI_EVENT_SCAN_FINISHED);
          return ret < 0 ? ret : -EIO;
        }
    }

  snprintf(command, sizeof(command), "wifiscan %d",
           CONFIG_LVGL_APP_UI_DEMO_WIFI_SCAN_WAIT_MS);
  ret = ui_demo_wifi_run_command(command, output,
                                 CONFIG_LVGL_APP_UI_DEMO_WIFI_CMD_OUTPUT_LEN);
  if (ret == 0 && !ui_demo_wifi_output_contains_failure(output))
    {
      count = ui_demo_wifi_parse_scan_output(output, aps,
                                             UI_DEMO_WIFI_MAX_APS);
    }

  pthread_mutex_lock(&g_wifi_lock);
  if (generation == g_wifi.generation)
    {
      g_wifi.scan_in_progress = false;
      g_wifi.enabled = true;

      if (ret < 0)
        {
          char detail[UI_DEMO_WIFI_MESSAGE_LEN];

          ui_demo_wifi_describe_command_error(ret, detail, sizeof(detail));
          g_wifi.status = UI_DEMO_WIFI_STATUS_ERROR;
          ui_demo_wifi_set_message_locked("WiFi 扫描失败：%s", detail);
        }
      else if (ui_demo_wifi_output_contains_failure(output))
        {
          g_wifi.status = UI_DEMO_WIFI_STATUS_ERROR;
          ui_demo_wifi_set_message_locked(
            "WiFi 扫描失败，请确认模块已启动并查看系统日志");
        }
      else
        {
          memcpy(g_wifi.aps, aps, sizeof(aps));
          g_wifi.ap_count = count;
          g_wifi.status = UI_DEMO_WIFI_STATUS_READY;

          if (count == 0)
            {
              ui_demo_wifi_set_message_locked(
                "未扫描到 WiFi，请靠近路由器后重新扫描");
            }
          else
            {
              ui_demo_wifi_set_message_locked("扫描完成，发现 %lu 个 WiFi",
                                              (unsigned long)count);
            }
        }
    }
  pthread_mutex_unlock(&g_wifi_lock);

  free(output);
  ui_demo_wifi_notify(UI_DEMO_WIFI_EVENT_SCAN_FINISHED);
  return ret;
}

static int ui_demo_wifi_connect_entry(int argc, char *argv[])
{
  char ssid[UI_DEMO_WIFI_SSID_LEN];
  char password[UI_DEMO_WIFI_PASSWORD_LEN];
  char quoted_ssid[UI_DEMO_WIFI_SSID_LEN * 2 + 4];
  char quoted_password[UI_DEMO_WIFI_PASSWORD_LEN * 2 + 4];
  char command[UI_DEMO_WIFI_SSID_LEN * 2 +
               UI_DEMO_WIFI_PASSWORD_LEN * 2 + 64];
  char *output;
  uint32_t generation;
  int wlan_ret = 0;
  int connect_status = 0;
  int dhcp_ret = 0;
  bool has_dhcp = false;
  bool has_connect_result = false;
  int ret;

  (void)argc;
  (void)argv;

  pthread_mutex_lock(&g_wifi_lock);
  ui_demo_wifi_copy_text(ssid, sizeof(ssid), g_wifi.pending_ssid);
  ui_demo_wifi_copy_text(password, sizeof(password), g_wifi.pending_password);
  generation = g_wifi.connect_generation;
  pthread_mutex_unlock(&g_wifi_lock);

  output = malloc(CONFIG_LVGL_APP_UI_DEMO_WIFI_CMD_OUTPUT_LEN);
  if (output == NULL)
    {
      pthread_mutex_lock(&g_wifi_lock);
      if (generation == g_wifi.generation)
        {
          g_wifi.connect_in_progress = false;
          g_wifi.status = UI_DEMO_WIFI_STATUS_ERROR;
          ui_demo_wifi_set_message_locked("内存不足，无法连接 WiFi");
        }
      pthread_mutex_unlock(&g_wifi_lock);
      ui_demo_wifi_notify(UI_DEMO_WIFI_EVENT_CONNECT_FINISHED);
      return -ENOMEM;
    }

  if (!ui_demo_wifi_quote_arg(ssid, quoted_ssid, sizeof(quoted_ssid)) ||
      !ui_demo_wifi_quote_arg(password, quoted_password,
                              sizeof(quoted_password)))
    {
      ret = -EINVAL;
      snprintf(output, CONFIG_LVGL_APP_UI_DEMO_WIFI_CMD_OUTPUT_LEN,
               "SSID 或密码包含不支持的字符");
    }
  else
    {
      snprintf(command, sizeof(command), "wificonnect %s %s %d",
               quoted_ssid, quoted_password,
               CONFIG_LVGL_APP_UI_DEMO_WIFI_CONNECT_TIMEOUT_MS);
      ret = ui_demo_wifi_run_command(command, output,
                                     CONFIG_LVGL_APP_UI_DEMO_WIFI_CMD_OUTPUT_LEN);
      has_connect_result =
        ui_demo_wifi_parse_connect_result(output, &wlan_ret,
                                          &connect_status,
                                          &dhcp_ret,
                                          &has_dhcp);
    }

  pthread_mutex_lock(&g_wifi_lock);
  if (generation == g_wifi.generation)
    {
      g_wifi.connect_in_progress = false;

      if (ret == 0 && has_connect_result &&
          wlan_ret == 0 && connect_status != 0 &&
          (!has_dhcp || dhcp_ret == 0))
        {
          g_wifi.enabled = true;
          g_wifi.status = UI_DEMO_WIFI_STATUS_CONNECTED;
          ui_demo_wifi_copy_text(g_wifi.connected_ssid,
