          ui_demo_wifi_set_message_locked("WiFi 连接成功：%s", ssid);
        }
      else if (ret == -EINVAL)
        {
          g_wifi.status = UI_DEMO_WIFI_STATUS_ERROR;
          ui_demo_wifi_set_message_locked("%s", output);
        }
      else if (ret < 0 && !has_connect_result)
        {
          char detail[UI_DEMO_WIFI_MESSAGE_LEN];

          ui_demo_wifi_describe_command_error(ret, detail, sizeof(detail));
          g_wifi.status = UI_DEMO_WIFI_STATUS_ERROR;
          ui_demo_wifi_set_message_locked("WiFi 连接失败：%s", detail);
        }
      else if (!has_connect_result)
        {
          g_wifi.status = UI_DEMO_WIFI_STATUS_ERROR;
          ui_demo_wifi_set_message_locked(
            "WiFi 连接失败：无法解析连接结果，请查看系统日志");
        }
      else if (wlan_ret != 0)
        {
          g_wifi.status = UI_DEMO_WIFI_STATUS_ERROR;
          ui_demo_wifi_set_message_locked(
            "WiFi 连接失败：可能是密码错误、认证失败、信号弱或网络已离线");
        }
      else if (connect_status == 0)
        {
          g_wifi.status = UI_DEMO_WIFI_STATUS_ERROR;
          ui_demo_wifi_set_message_locked(
            "WiFi 连接超时：请检查 SSID、密码和路由器信号");
        }
      else if (has_dhcp && dhcp_ret != 0)
        {
          g_wifi.status = UI_DEMO_WIFI_STATUS_ERROR;
