      if (idle_ms < CONFIG_LVGL_APP_APP_MAIN_LOOP_MIN_SLEEP_MS)
        {
          idle_ms = CONFIG_LVGL_APP_APP_MAIN_LOOP_MIN_SLEEP_MS;
