}

static void wificonnect_usage(void)
{
  printf("Usage: wificonnect <ssid> [password] [timeout_ms]\n");
  printf("Default timeout_ms is 15000. Use an empty password for open AP.\n");
}

static int wificonnect_worker(void *arg)
{
