static int32_t ui_demo_wifi_signal_from_rssi(int32_t rssi)
{
  if (rssi == 0)
    {
      return 0;
    }

  if (rssi >= -35)
    {
      return 100;
    }

  if (rssi <= -95)
    {
      return 5;
    }

  return 5 + ((rssi + 95) * 95) / 60;
}

static bool ui_demo_wifi_parse_scan_line(const char *line,
                                         struct ui_demo_wifi_ap *ap)
{
  const char *ssid_start;
  const char *ssid_end;
  const char *channel_pos;
  const char *rssi_pos;
  unsigned long channel = 0;
  long rssi = 0;
  size_t ssid_len;

  if (line == NULL || ap == NULL)
    {
      return false;
    }

  ssid_start = strstr(line, "ssid=\"");
  if (ssid_start == NULL)
    {
      return false;
    }

  ssid_start += strlen("ssid=\"");
  ssid_end = strchr(ssid_start, '"');
  if (ssid_end == NULL || ssid_end == ssid_start)
    {
      return false;
    }

  memset(ap, 0, sizeof(*ap));
  ssid_len = (size_t)(ssid_end - ssid_start);
  if (ssid_len >= sizeof(ap->ssid))
    {
      ssid_len = sizeof(ap->ssid) - 1;
    }

  memcpy(ap->ssid, ssid_start, ssid_len);
  ap->ssid[ssid_len] = '\0';

  channel_pos = strstr(line, "ch=");
  if (channel_pos != NULL)
    {
      (void)sscanf(channel_pos, "ch=%lu", &channel);
    }

  rssi_pos = strstr(line, "rssi=");
  if (rssi_pos != NULL)
    {
      (void)sscanf(rssi_pos, "rssi=%ld", &rssi);
    }

  ap->channel = (uint32_t)channel;
  ap->rssi = (int32_t)rssi;
  ap->signal = ui_demo_wifi_signal_from_rssi(ap->rssi);
  snprintf(ap->status, sizeof(ap->status),
           "CH %lu  RSSI %ld dBm", channel, rssi);

  return true;
}

