static bool ui_demo_wifi_quote_arg(const char *src, char *dst, size_t dst_len)
{
  size_t used = 0;

  if (src == NULL || dst == NULL || dst_len < 3)
    {
      return false;
    }

  dst[used++] = '"';
  while (*src != '\0')
    {
      char ch = *src++;

      if (ch == '\n' || ch == '\r')
        {
          return false;
        }

      if (ch == '"' || ch == '\\')
        {
          if (used + 2 >= dst_len)
            {
              return false;
            }

          dst[used++] = '\\';
          dst[used++] = ch;
        }
      else
        {
          if (used + 1 >= dst_len)
            {
              return false;
            }

          dst[used++] = ch;
        }
    }

  if (used + 1 >= dst_len)
    {
      return false;
    }

  dst[used++] = '"';
  dst[used] = '\0';
  return true;
}

