static bool ui_demo_wifi_password_is_hex64(const char *password)
{
  size_t i;

  if (password == NULL || strlen(password) != 64)
    {
      return false;
    }

  for (i = 0; i < 64; i++)
    {
      char ch = password[i];

      if (!((ch >= '0' && ch <= '9') ||
            (ch >= 'a' && ch <= 'f') ||
            (ch >= 'A' && ch <= 'F')))
        {
          return false;
        }
    }

  return true;
}

