        {
          if (ap->rssi > aps[i].rssi)
            {
              aps[i] = *ap;
            }

          return;
        }
    }

  if (*count < UI_DEMO_WIFI_MAX_APS)
    {
      aps[*count] = *ap;
      (*count)++;
    }
}

static uint32_t ui_demo_wifi_channel_from_freq(uint32_t freq)
{
  if (freq >= 2412 && freq <= 2472)
    {
      return (freq - 2407) / 5;
    }

  if (freq == 2484)
    {
      return 14;
    }

  if (freq >= 5000 && freq <= 5900)
    {
      return (freq - 5000) / 5;
    }

  return freq;
}

