      if (!result.valid_flag)
        {
          continue;
        }

      ssid_len = result.ssid.length;
      if (ssid_len > AIC_WIFI_SSID_MAX_LEN)
        {
          ssid_len = AIC_WIFI_SSID_MAX_LEN;
        }

      memcpy(ap->ssid, result.ssid.array, ssid_len);
