static int wificonnect_is_number(const char *str)
{
  if (!str || !*str)
    return 0;

  if (str[0] == '-' && str[1] != '\0')
    {
      str++;
    }

  while (*str)
    {
      if (!isdigit((unsigned char)*str++))
        return 0;
    }

  return 1;
